model EventEnvelope {
  specversion: string = "1.0";
  id: string;
  type: string = "ShoppingCart.CartCreated";
  source: string = "/carts";
  data: EventData;
}

model EventData {
  cart: ShoppingCart;
}

model ShoppingCart {
  items: CartItem[];
  currency: string;
  subtotal: int64;
  status: CartStatus;
  customerReference?: string;
  expiresAt?: utcDateTime;
}

model CartItem {
  variantReference: string;
  productTitle: string;
  variantDescription?: string;
  sku?: string;
  unitPrice: int64;
  quantity: int32;
}

enum CartStatus {
  Active: "active",
  Converted: "converted",
  Abandoned: "abandoned",
}
